package com.ragestars.overlay;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.widget.*;import org.json.JSONObject;import java.util.concurrent.*;
public class MainActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private LicenseStore store;private LinearLayout root;private TextView status;
 public void onCreate(Bundle b){super.onCreate(b);store=new LicenseStore(this);showStart();}
 private void base(String title){root=new LinearLayout(this);root.setOrientation(1);root.setPadding(28,32,28,28);root.setBackgroundColor(0xFF100B0F);TextView h=new TextView(this);h.setText(title);h.setTextColor(0xFFFF4968);h.setTextSize(28);h.setTypeface(null,1);root.addView(h);status=new TextView(this);status.setTextColor(0xFFE8DDE1);status.setPadding(0,18,0,18);root.addView(status);setContentView(root);}
 private Button button(String s){Button b=new Button(this);b.setText(s);b.setTextColor(-1);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xFFB51F42));return b;}
 private void showStart(){base("RAGESTARS");status.setText("Проверка лицензии…");worker.execute(()->{try{String t=store.token(),id=store.licenseId();if(t==null||id==null){runOnUiThread(this::showActivation);return;}Api.check(id,t,store.installationId());runOnUiThread(this::showPermissions);}catch(Exception e){store.clear();runOnUiThread(this::showActivation);}});}
 private void showActivation(){base("АКТИВАЦИЯ");status.setText("Введите одноразовый код доступа.");EditText code=new EditText(this);code.setSingleLine(true);code.setHint("КОД АКТИВАЦИИ");code.setTextColor(-1);root.addView(code);Button go=button("АКТИВИРОВАТЬ");root.addView(go);go.setOnClickListener(v->{String value=code.getText().toString().trim();if(value.isEmpty()){status.setText("Введите код.");return;}go.setEnabled(false);status.setText("Проверяем код…");worker.execute(()->{try{JSONObject r=Api.activate(value,store.installationId());store.save(r.getString("license_id"),r.getString("token"));runOnUiThread(this::showPermissions);}catch(Exception e){runOnUiThread(()->{go.setEnabled(true);status.setText("Ошибка: "+e.getMessage());});}});});}
 private void showPermissions(){base("RAGESTARS");status.setText("Лицензия активна. Разрешите отображение меню поверх игры.");Button overlay=button("РАЗРЕШИТЬ ОКНО");root.addView(overlay);overlay.setOnClickListener(v->{if(!Settings.canDrawOverlays(this))startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));else startMenu();});if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=0)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},7);Button start=button("ЗАПУСТИТЬ МЕНЮ");root.addView(start);start.setOnClickListener(v->startMenu());}
 private void startMenu(){if(!Settings.canDrawOverlays(this)){status.setText("Сначала разрешите отображение поверх других приложений.");return;}Intent i=new Intent(this,FloatingMenuService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);status.setText("Плавающая кнопка запущена. Перейдите в игру.");}
 protected void onDestroy(){super.onDestroy();worker.shutdown();}
}
